"""Build the four code-native motion concepts. No generated bitmap artwork."""
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
DATA={
'kin':dict(name='kin',tag='A little more human',title='Good support.<br>A great little <em>team.</em>',desc='Your people, your conversations. All together.',signup='Make room for<br><em>good conversations.</em>',signupdesc='A calmer inbox starts with a small hello.',forgot='We’ll get you<br><em>back together.</em>',forgotdesc='Enter your work email. We’ll send a link to reset your password.',fonts='DM+Sans:wght@400;500;600;700&family=DM+Serif+Display:ital@0;1',tabs=[('tray','Inbox'),('users','Team'),('chart-line-up','Insights'),('gear-six','Settings')],mark='<path d="M5 18V6m0 8 7-8m-7 8 8 5M18 6v13"/>'),
'inkling':dict(name='inkling',tag='A little motion goes a long way',title='Small frames.<br><em>Big feelings.</em>',desc='A place for the things only you can bring to life.',signup='Every great loop<br>starts <em>somewhere.</em>',signupdesc='Your first blank page is waiting.',forgot='A little<br><em>memory lapse?</em>',forgotdesc='Leave your email. We’ll pencil in a fresh start.',fonts='Outfit:wght@400;500;600&family=Caveat:wght@400;500',tabs=[('squares-four','Studio'),('film-strip','Loops'),('lightbulb','Learn'),('user-circle','You')],mark='<path d="M4 17C1 3 23 2 20 13c-2 7-15 10-14 3 1-5 14-5 15 4"/>'),
'draft':dict(name='draft',tag='Better, together',title='Your next idea<br>has <em>company.</em>',desc='A shared canvas for whatever comes next.',signup='An open canvas.<br><em>An open mind.</em>',signupdesc='Bring your team. Leave the perfect plan behind.',forgot='Let’s draw<br><em>a way back.</em>',forgotdesc='We’ll send a reset link to your email. Your boards will be right here.',fonts='Geist:wght@400;500;600&family=Geist+Mono:wght@400;500',tabs=[('squares-four','Boards'),('users-three','Team'),('stack','Templates'),('user-circle','You')],mark='<path d="M4 5h10l6 6v9H4V5Zm10 0v6h6M8 15h7"/>'),
'pulse':dict(name='pulse',tag='Quietly keeping watch',title='Less checking.<br><em>More peace of mind.</em>',desc='Your services are in good hands. Take a breath.',signup='Good things<br>are <em>up ahead.</em>',signupdesc='Your first monitor is a minute away.',forgot='A brief<br><em>interruption.</em>',forgotdesc='Enter your email and we’ll help restore your connection.',fonts='DM+Sans:wght@400;500;600&family=Martian+Mono:wght@400;500',tabs=[('activity','Overview'),('broadcast','Monitors'),('warning-circle','Incidents'),('gear-six','Settings')],mark='<path d="M2 13h5l3-8 4 15 3-7h5"/>')}
def icon(n):return f'<i class="ph ph-{n}" aria-hidden="true"></i>'
def field(id,label,type='text',extra='',placeholder=''):
    pw=type=='password'
    eye=f'<button class="eye" type="button" data-toggle-pw aria-label="Show password" aria-pressed="false">{icon("eye")}{icon("eye-slash")}</button>' if pw else ''
    return f'<div class="field"><label for="{id}">{label}</label><div class="control"><input id="{id}" type="{type}" required placeholder="{placeholder}" aria-describedby="{id}-err" {extra}>{eye}</div><p id="{id}-err" class="field-error" role="alert"></p></div>'
def btn(label):return f'<button class="btn" type="submit"><span class="btn-label">{label} {icon("arrow-right")}</span><span class="spinner" aria-hidden="true"></span></button>'
def social():return f'<div class="or">or continue with</div><div class="socials"><button type="button" class="btn-ghost" data-social="Apple">{icon("apple-logo")} Apple</button><button type="button" class="btn-ghost" data-social="Google">{icon("google-logo")} Google</button></div>'
def art(kind,small=False):
    if kind=='kin':return '<div class="crew" aria-label="Four friendly teammates. Tap to say hello." role="group">'+''.join(f'<button class="pal pal-{i}" aria-label="Say hello to {n}"><span class="pal-eyes"><b></b><b></b></span><span class="pal-mouth"></span></button>' for i,n in enumerate(['Maya','Jun','Theo','Pip']))+'<span class="crew-bubble" aria-live="polite">We’ve got you.</span></div>'
    if kind=='inkling':return '<div class="doodle-wrap"><svg class="doodle" viewBox="0 0 300 150" fill="none" aria-hidden="true"><path class="ground" d="M55 126Q155 122 245 127"/><g class="onion red"><path d="M121 95C89 74 110 13 148 20S198 59 177 90Q154 119 121 95Z"/></g><g class="onion blue"><path d="M137 95C105 74 126 13 164 20S214 59 193 90Q170 119 137 95Z"/></g><g class="bean"><path class="body-line" d="M129 95C97 74 118 13 156 20S206 59 185 90Q162 119 129 95Z"/><path class="legs" d="m140 103-12 22m38-21 13 21m-53-48-20 8m85-15 17-9"/><g class="doodle-eyes"><path d="M148 56v5m19-5v5"/><path class="smile" d="M150 72q8 6 15-1"/></g><path class="blindfold" d="m135 53 44 4m-43 4 44-4m-43 2 42 4"/></g></svg><span class="handnote">a work in progress. like all of us.</span></div>'
    if kind=='draft':return '<div class="board-scene"><div class="sticky s1">what if<br><strong>we tried this?</strong><span>↗</span></div><div class="sticky s2">make room<br>for the messy bit.</div><svg class="board-line" viewBox="0 0 320 150" fill="none" aria-hidden="true"><path d="M105 100q50 40 92-13t65 3m-8-10 9 10-14 4"/></svg><div class="collab c1"><svg viewBox="0 0 20 23"><path d="M2 1v18l5-5 4 7 3-2-4-7 7-1Z"/></svg><span>Maya</span></div><div class="collab c2"><svg viewBox="0 0 20 23"><path d="M2 1v18l5-5 4 7 3-2-4-7 7-1Z"/></svg><span>Jun</span></div><div class="collab c3"><svg viewBox="0 0 20 23"><path d="M2 1v18l5-5 4 7 3-2-4-7 7-1Z"/></svg><span>Theo</span></div></div>'
    return '<div class="signal-scene"><div class="signal-label"><span class="live-dot"></span><span data-signal-label>All systems operational</span><span class="signal-ms"><b data-ms>142</b> ms</span></div><svg class="signal" viewBox="0 0 360 120" preserveAspectRatio="none" aria-label="Live response signal"><defs><linearGradient id="fade"><stop stop-color="#99c8b0" stop-opacity="0"/><stop offset=".3" stop-color="#76ae91"/><stop offset="1" stop-color="#76ae91"/></linearGradient></defs><path class="signal-path" d="M0 70H66l9-6 7 12 12-6h29l9-21 9 44 12-67 11 44h30l7-5 7 10 9-5h143"/></svg><div class="signal-footer"><span>CONNECTED · EU WEST</span><span class="signal-beacon"></span><span>LIVE</span></div></div>'
def home(k):
    if k=='kin':return '''<div class="home-heading"><p class="eyebrow">Monday, November 9</p><h1 class="display" id="home-title">Hey, Maya.<br>Let’s make <em>their day.</em></h1></div><div class="crew-home">'''+art(k)+'''</div><div class="queue-banner"><div><span class="eyebrow">Your inbox</span><p><b data-queue>8</b> waiting for a little help</p></div><span class="queue-spark">✳</span></div><div class="section-title"><h2>Next in line</h2><button class="text-button" data-action="queue">View all →</button></div><div class="ticket-list"><button class="ticket" data-ticket="Lena"><span class="person peach">L</span><span><strong>Lena Park</strong><small>Can I change my delivery address?</small><em>Orders · 2 min ago</em></span><span class="unread"></span></button><button class="ticket" data-ticket="Omar"><span class="person sage">O</span><span><strong>Omar Hassan</strong><small>A quick question about my plan</small><em>Billing · 6 min ago</em></span></button><button class="ticket" data-ticket="Nina"><span class="person sky">N</span><span><strong>Nina Chen</strong><small>Thanks, that worked perfectly!</small><em>Feedback · 12 min ago</em></span></button></div>'''
    if k=='inkling':return '''<div class="home-heading"><p class="eyebrow">Your little animation studio</p><h1 class="display" id="home-title">Morning, Remi.<br><em>Make something move.</em></h1></div><div class="project-feature"><div class="project-top"><span>01 / THE DAILY DOODLE</span><button data-action="play" aria-label="Pause animation">Ⅱ</button></div>'''+art(k)+'''<div class="project-bottom"><div><h2>A walk to nowhere</h2><p>12 frames · 12 fps · Edited just now</p></div><button class="round-action" data-action="edit" aria-label="Open animation editor">↗</button></div></div><div class="timeline-wrap"><div class="timeline-label"><span>ONION SKIN <b>ON</b></span><span>FRAME <b data-frame>06</b> / 12</span></div><input class="timeline" type="range" min="1" max="12" value="6" aria-label="Animation frame"><div class="frame-ticks" aria-hidden="true">│ │ │ │ │ │ │ │ │ │ │ │</div></div><div class="section-title"><h2>On your desk</h2><button class="text-button" data-action="new">＋ New loop</button></div><div class="sketch-projects"><button data-project="The almost-flying kite"><span class="mini-sketch kite">♢</span><strong>The almost-flying kite</strong><small>24 frames · Yesterday</small></button><button data-project="A very small hello"><span class="mini-sketch hello">〰</span><strong>A very small hello</strong><small>8 frames · Sunday</small></button></div>'''
    if k=='draft':return '''<div class="home-heading"><p class="eyebrow">The good ideas club <span class="live-dot"></span></p><h1 class="display" id="home-title">Morning, Alex.<br><em>Meet you on the canvas.</em></h1></div><div class="live-board"><div class="board-top"><span><span class="live-dot"></span>3 minds at work</span><span class="avatar-stack"><i>M</i><i>J</i><i>T</i></span></div>'''+art(k)+'''<button class="board-open" data-action="board"><span><strong>The next big little thing</strong><small>Jun is adding a thought…</small></span><span>↗</span></button></div><div class="section-title"><h2>Your boards</h2><button class="text-button" data-action="new">＋ New board</button></div><div class="boards"><button class="board-row" data-project="A gentler onboarding"><span class="board-thumb"><i></i><i></i><i></i></span><span><strong>A gentler onboarding</strong><small>Product team · Edited 2h ago</small></span><span>↗</span></button><button class="board-row" data-project="Friday’s loose ends"><span class="board-thumb pink"><i></i><i></i></span><span><strong>Friday’s loose ends</strong><small>Just you · Edited yesterday</small></span><span>↗</span></button></div><div class="draft-tip">A half-formed thought is a good place to start. <span>↗</span></div>'''
    return '''<div class="home-heading"><p class="eyebrow">Good morning, Jules</p><h1 class="display" id="home-title">Everything’s<br><em>looking good.</em></h1><p class="lede"><span class="live-dot"></span>All 6 services operational</p></div><div class="uptime-hero"><div class="uptime-number">99.98<span>%</span></div><p>UPTIME · LAST 30 DAYS</p><div class="chart-interact" tabindex="0" role="slider" aria-label="Response time history" aria-valuemin="0" aria-valuemax="29" aria-valuenow="14"><svg viewBox="0 0 340 90" preserveAspectRatio="none" aria-hidden="true"><path class="area" d="M0 65C15 65 20 48 35 53S60 60 80 46S110 50 125 43S145 52 165 38S195 47 210 35S240 44 255 31S285 34 300 24S325 31 340 27V90H0Z"/><path class="chart-line" d="M0 65C15 65 20 48 35 53S60 60 80 46S110 50 125 43S145 52 165 38S195 47 210 35S240 44 255 31S285 34 300 24S325 31 340 27"/></svg><span class="scrubber"></span></div><div class="chart-meta"><span data-chart-day>Today, 09:41</span><span><b data-chart-ms>142</b> ms avg.</span></div></div><div class="section-title"><h2>Your services</h2><button class="text-button" data-action="new">＋ Monitor</button></div><div class="services">'''+''.join(f'<button class="service" data-service="{n}"><span class="live-dot"></span><span><strong>{n}</strong><small>{url}</small></span><svg viewBox="0 0 65 25" aria-hidden="true"><path d="M0 18l8-3 8 2 8-10 8 8 8-4 8 3 9-7 8 2"/></svg><span>{ms}<small>ms</small></span></button>' for n,url,ms in [('API','api.acme.co','142'),('Storefront','shop.acme.co','218'),('Database','db.production','36')])+'''</div><div class="region-row"><span class="region-ping"></span><span>Frankfurt</span><span class="region-ping"></span><span>Virginia</span><span class="region-ping"></span><span>Singapore</span></div>'''
for k,d in DATA.items():
    mark=f'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">{d["mark"]}</svg>'
    brand=f'<span class="brand">{mark}{d["name"]}</span>'
    top=f'<div class="top">{brand}<span class="meta">{ "Made for people" if k=="kin" else "Make a little space" if k=="inkling" else "Room for everyone" if k=="draft" else "You’re connected"}</span></div>'
    back=f'<div class="top"><button class="back" data-go="signin" aria-label="Back to sign in">{icon("arrow-left")}</button>{brand}</div>'
    signin=top+f'<div class="auth-hero"><div class="art-slot">{art(k)}</div><div class="auth-copy"><h1 class="display" id="si-title">{d["title"]}</h1><p class="lede">{d["desc"]}</p></div></div><form class="form" data-form="signin">'+field('si-email','Email or phone','text','autocomplete="username" inputmode="email" data-kind="email-or-phone"','you@yourteam.com')+'<div class="label-row"><span></span><a data-go="forgot" href="#forgot">Forgot password?</a></div>'+field('si-pw','Password','password','autocomplete="current-password" data-minlength="6"','Your password')+btn('Welcome back')+social()+'</form><p class="foot">New around here? <a href="#signup" data-go="signup">Create an account</a></p>'
    signup=back+f'<div class="small-art">{art(k)}</div><div class="signup-head"><h1 class="display" id="su-title">{d["signup"]}</h1><p class="lede">{d["signupdesc"]}</p></div><form class="form" data-form="signup">'+field('su-name','Your name','text','autocomplete="given-name"','What should we call you?')+field('su-email','Email','email','autocomplete="email"','you@yourteam.com')+field('su-pw','Create a password','password','autocomplete="new-password" data-minlength="8" data-strength="strength"','At least 8 characters')+'<div id="strength" class="meter" data-empty="Make it a good one"><i></i><i></i><i></i><i></i><span data-meter-label></span></div><div class="field"><label class="check"><input type="checkbox" required aria-describedby="terms-err"><span>I agree to the <a href="#" data-legal="Terms">Terms</a> and <a href="#" data-legal="Privacy">Privacy Policy</a>.</span></label><p id="terms-err" class="field-error" role="alert"></p></div>'+btn('Let’s get started')+social()+'</form><p class="foot">Already part of the crew? <a href="#signin" data-go="signin">Sign in</a></p>'
    forgot=back+f'<div class="forgot-art">{art(k)}</div><div data-when="form"><div class="pad"><h1 class="display" id="fp-title">{d["forgot"]}</h1><p class="lede">{d["forgotdesc"]}</p></div><form class="form" data-form="forgot">'+field('fp-email','Email','email','autocomplete="email"','you@yourteam.com')+btn('Send reset link')+'</form><p class="foot"><a href="#signin" data-go="signin">Back to sign in</a></p></div><div data-when="sent" aria-live="polite"><div class="pad"><p class="eyebrow">A fresh start</p><h2 class="display" style="margin-top:12px">Check your<br><em>inbox.</em></h2><p class="lede">We’ve sent a reset link to</p><span class="sent-email" data-sent-email>you@yourteam.com</span><p class="lede">The demo email is on its way. In a real app, your link would expire in 15 minutes.</p></div><div class="form"><button class="btn" data-go="signin">Back to sign in</button><button class="resend" data-resend data-seconds="30">Resend <span data-count>0:30</span></button><button class="resend" data-reset-state>Use a different email</button></div></div>'
    tabs='<nav class="tabbar" role="tablist" aria-label="Main">'+''.join(f'<button role="tab" aria-selected="{str(i==0).lower()}" data-home-tab="{label}">{icon(ic)}<span>{label}</span></button>' for i,(ic,label) in enumerate(d['tabs']))+'</nav>'
    homes=f'<div class="top">{brand}<button class="avatar" data-profile aria-label="Open profile">{dict(kin="M",inkling="R",draft="A",pulse="J")[k]}</button></div>'+home(k)+tabs
    sections=''.join(f'<section class="screen {"home" if n=="home" else ""}" data-screen="{n}" aria-labelledby="{lab}">{s}</section>' for n,lab,s in [('signin','si-title',signin),('signup','su-title',signup),('forgot','fp-title',forgot),('home','home-title',homes)])
    html=f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>{d["name"].title()} — {d["tag"]}</title><link rel="preconnect" href="https://fonts.googleapis.com"><link href="https://fonts.googleapis.com/css2?family={d["fonts"]}&display=swap" rel="stylesheet"><link rel="stylesheet" href="https://unpkg.com/@phosphor-icons/web@2.1.1/src/regular/style.css"><link rel="stylesheet" href="../../shared/base.css"><link rel="stylesheet" href="../../shared/ui.css"><link rel="stylesheet" href="theme.css"></head><body><div class="app">{sections}<div class="toast" role="status" aria-live="polite"></div><div class="modal" hidden><div class="modal-card" role="dialog" aria-modal="true" aria-labelledby="modal-title"><button class="modal-close" aria-label="Close">×</button><p class="eyebrow">{d["name"]} · Interactive concept</p><h2 id="modal-title"></h2><div class="modal-body"></div></div></div></div><script src="../../shared/app.js"></script><script src="../../shared/interactions.js"></script><script src="theme.js"></script></body></html>'
    folder=ROOT/'themes'/k;folder.mkdir(parents=True,exist_ok=True);(folder/'index.html').write_text(html,encoding='utf-8')
print('Built Kin, Inkling, Draft, Pulse: 16 screens')
